code_question:
def solution() -> int:
    arr = [6, 13, 14]
    left, right = 0, len(arr) - 1
    target = 6
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

