from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    # adjacency list for the undirected graph
    adj = {
        0: [(3, 7)],
        1: [(3, 2), (4, 6), (2, 6)],
        2: [(0, 7), (1, 6), (3, 5)],
        3: [(0, 7), (2, 5), (1, 2)],
        4: [(1, 6)]
    }

    start, end = 0, 4
    # Dijkstra's algorithm
    dist = {node: float('inf') for node in adj}
    prev = {node: None for node in adj}
    dist[start] = 0
    pq: List[Tuple[int, int]] = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        if u == end:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))

    # reconstruct path
    if dist[end] == float('inf'):
        return ([], -1)
    path = []
    cur = end
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return (path, dist[end])

