    # Adjacency list for an undirected graph
    graph = {
        0: [(1, 3), (4, 7), (5, 1)],
        1: [(0, 3), (3, 5)],
        2: [(5, 8)],
        3: [(4, 6), (1, 5)],
        4: [(3, 6), (0, 7), (5, 5)],
        5: [(2, 8), (0, 1), (4, 5)]
    }

    import heapq

    start, target = 0, 5
    dist = {node: float("inf") for node in graph}
    prev = {node: None for node in graph}
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, node = heapq.heappop(heap)
        if d != dist[node]:
            continue
        if node == target:
            break
        for neighbor, w in graph[node]:
            nd = d + w
            if nd < dist[neighbor]:
                dist[neighbor] = nd
                prev[neighbor] = node
                heapq.heappush(heap, (nd, neighbor))

    if dist[target] == float("inf"):
        return [], -1

    path = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return path, int(dist[target])
