from collections import deque

def solution() -> dict[int, str]:
    # Graph adjacency list
    graph = {
        1: {2, 3},
        2: {1, 5, 6},
        3: {1, 5, 6},
        4: {6},
        5: {2, 3},
        6: {2, 3, 4}
    }
    # Colors mapping: 0 -> 'A', 1 -> 'B'
    color_map = {}
    for start in graph:
        if start not in color_map:
            # BFS to assign colors to each component
            queue = deque([start])
            color_map[start] = 0
            while queue:
                v = queue.popleft()
                for neigh in graph[v]:
                    if neigh not in color_map:
                        color_map[neigh] = 1 - color_map[v]
                        queue.append(neigh)
                    elif color_map[neigh] == color_map[v]:
                        # Not bipartite – should not happen for this graph
                        raise ValueError("Graph is not bipartite")
    # Convert numeric colors to letters
    result = {vertex: ('A' if col == 0 else 'B') for vertex, col in color_map.items()}
    return result

