def solution() -> Dict[int, str]:
    Return a valid vertex‑coloring for the given graph.
    The graph is:
        2–4, 2–5, 3–4, 3–5
    with vertices 1 and 6 isolated.

    # adjacency list representation
    graph = {
        1: [],
        2: [4, 5],
        3: [4, 5],
        4: [2, 3],
        5: [2, 3],
        6: []
    }
    # available colors (using three because the sub‑graph is not bipartite)
    colors = ['A', 'B', 'C']
    assignment: Dict[int, str] = {}

    # Greedy coloring in order 1..6
    for v in range(1, 7):
        used = {assignment[n] for n in graph[v] if n in assignment}
        for c in colors:
            if c not in used:
                assignment[v] = c
                break
    return assignment

